import numpy as np
from scipy import stats

def _fit(X, y, it=30):
    X = np.column_stack([np.ones(len(y)), X]) if X.size else np.ones((len(y), 1))
    b = np.zeros(X.shape[1])
    for _ in range(it):
        p = 1 / (1 + np.exp(-np.clip(X @ b, -30, 30)))
        w = p * (1 - p) + 1e-9
        H = X.T @ (X * w[:, None]) + 1e-6 * np.eye(X.shape[1])
        step = np.linalg.solve(H, X.T @ (y - p))
        b += step
        if np.max(np.abs(step)) < 1e-7:
            break
    p = np.clip(1 / (1 + np.exp(-np.clip(X @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return float(np.sum(y * np.log(p) + (1 - y) * np.log(1 - p)))

def design(feats):
    x, y, ids = np.asarray(feats.x, float), np.asarray(feats.y, float), list(feats.ids)
    n, P = x.shape
    labs = sorted(set(feats.stratum))
    S = np.column_stack([[s == l for s in feats.stratum] for l in labs[1:]]).astype(float) if len(labs) > 1 else np.zeros((n, 0))
    R = np.corrcoef(x, rowvar=False)
    base = lambda cols, extra=None: np.column_stack([S] + [x[:, cols]] + ([extra] if extra is not None else []))
    ll = lambda cols, extra=None: _fit(base(cols, extra), y)
    sel, cur = [], ll([])
    while len(sel) < MAX_DRIVERS:
        alpha = (0.05 if not sel else 0.02) / P
        cand = [j for j in range(P) if j not in sel and all(abs(R[j, k]) < 0.9 for k in sel)]
        if not cand:
            break
        gains = [2 * (ll(sel + [j]) - cur) for j in cand]
        g = int(np.argmax(gains))
        if stats.chi2.sf(gains[g], 1) > alpha:
            break
        sel.append(cand[g]); cur = ll(sel)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (cur - ll(rest)), 1) > 0.01 / P:
                sel = rest; cur = ll(sel); changed = True; break
    for i, j in enumerate(list(sel)):
        others = [k for k in sel if k != j]
        clus = {j} | {k for k in range(P) if abs(R[j, k]) >= 0.6 and k not in others}
        clus |= {m for k in list(clus) for m in range(P) if abs(R[k, m]) >= 0.6 and m not in others}
        if len(clus) == 1:
            continue
        def cost(c):
            l0 = ll(others + [c])
            return sum(max(0.0, ll(others + [c, m]) - l0) for m in clus if m != c)
        sel[i] = min(sorted(clus), key=cost)
    cur = ll(sel)
    prods, pa = [], 0.01 / (P * (P + 1) / 2)
    for a in range(P):
        for b in range(a, P):
            if a != b and abs(R[a, b]) >= 0.6:
                continue
            mains = sorted(set(sel) | {a, b})
            l0 = ll(mains)
            g = 2 * (ll(mains, x[:, a] * x[:, b]) - l0)
            pv = stats.chi2.sf(g, 1)
            if pv < pa:
                prods.append((pv, a, b))
    prods = sorted(prods)[:2]
    drivers = list(sel)
    for _, a, b in prods:
        for k in (a, b):
            if k not in drivers:
                drivers.append(k)
    drivers = drivers[:MAX_DRIVERS]
    return Design(drivers=tuple(ids[k] for k in drivers),
                  columns=tuple(ids[k] for k in sorted(set(drivers))),
                  products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

